253	    @Override
254	    @Transactional
255	    public void saveOwner(Owner owner) throws DataAccessException {
256	        boolean isNew = owner.isNew();
257	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
258	        // roll it forward to the next business day so it never lands on a weekend. Everything
259	        // derived from the registration date below must use this adjusted value.
260	        LocalDate registrationDate = toBusinessDay(
261	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
262	        owner.setRegistrationDate(registrationDate);
263	        if (owner.isNew()) {
264	            // Resolve the household first so the owner's householdId is part of its identityKey. The
265	            // members are existing owners with the same last name and address; joining them makes this
266	            // owner share their stable householdId (back-filled onto any member still missing it).
267	            List<Owner> householdMembers = findHouseholdMembers(owner);
268	            if (!householdMembers.isEmpty()) {
269	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
270	            }
271	            // Size of the household after this create: the existing members plus this new owner.
272	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
273	        }
274	        // Single consolidated duplicate check: reject only when the new owner's WHOLE identityKey
275	        // (normalizedTelephone | email-or-empty | householdId) equals an existing owner's. This
276	        // subsumes the former separate telephone, email and household checks.
277	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
278	            throw new DuplicateIdentityException(owner.getIdentityKey());
279	        }
280	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's last name and
281	        // postcode while carrying a different telephone. Still created, but flagged as a possible
282	        // duplicate pointing at the matching owner.
283	        if (owner.isNew()) {
284	            Owner softMatch = findPossibleDuplicate(owner);
285	            if (softMatch != null) {
286	                owner.setPossibleDuplicate(true);
287	                owner.setPossibleDuplicateOf(softMatch.getId());
288	            }
289	        }
290	        if (owner.isNew()
291	            && countOwnersInCity(owner) >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
292	            throw new CityOwnerLimitExceededException(owner.getCity());
293	        }
294	        if (owner.isNew()
295	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
296	            throw new DailyOwnerLimitExceededException(registrationDate);
297	        }
298	        if (owner.isNew() && owner.getCustomerCode() == null) {
299	            owner.setCustomerCode(generateCustomerCode(owner));
300	        }
301	        if (owner.isNew()) {
302	            owner.setNamesakeCount(countNamesakes(owner));
303	            owner.setBulkSignupWarning(
304	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
305	        }
306	        if (owner.getMembershipNumber() == null) {
307	            owner.setMembershipNumber(generateMembershipNumber(owner));
308	        }
309	        ownerRepository.save(owner);
310	        if (isNew) {
311	            AUDIT.info("owner created id={} customerCode={} membershipLevel={} registrationDate={}",
312	                owner.getId(), owner.getCustomerCode(), owner.getMembershipLevel(),
313	                owner.getRegistrationDate());
314	        }
315	    }
316	
317	    /**
318	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
319	     * owner. The key consolidates telephone, email and household into one value, so two owners
320	     * collide only when their whole key is equal (see {@link Owner#getIdentityKey()}). By this point
321	     * the owner's {@code householdId} has been resolved, so its key is complete.
322	     */
323	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
324	        String identityKey = owner.getIdentityKey();
325	        return ownerRepository.findAll().stream()
326	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
327	    }
328	
329	    /**
330	     * Find an existing owner this (new) owner soft-matches against: one sharing the same last name
331	     * (compared case-insensitively with collapsed whitespace, like household matching) and the same
332	     * postcode, but carrying a different telephone. Returns the lowest-id such owner, or {@code null}
333	     * when the owner has no last name or postcode to match on, or nothing matches. The caller only
334	     * invokes this once the hard {@code identityKey} duplicate check has already passed.
335	     */
336	    private Owner findPossibleDuplicate(Owner owner) {
337	        String lastName = normalizeHouseholdKey(owner.getLastName());
338	        String postcode = owner.getPostcode();
339	        if (lastName == null || postcode == null || postcode.isBlank()) {
340	            return null;
341	        }
342	        String telephone = owner.getTelephone();
343	        return ownerRepository.findAll().stream()
344	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
345	                && postcode.equals(existing.getPostcode())
346	                && !Objects.equals(telephone, existing.getTelephone()))
347	            .min(Comparator.comparing(Owner::getId))
348	            .orElse(null);
349	    }
350	
351	    /**
352	     * Count the owners that already exist (before this create) sharing the same first name and last
353	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
354	     * unique among the existing owners.
355	     */
356	    private int countNamesakes(Owner owner) {
357	        String firstName = owner.getFirstName();
358	        String lastName = owner.getLastName();
359	        if (firstName == null || lastName == null) {
360	            return 0;
361	        }
362	        return (int) ownerRepository.findAll().stream()
363	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
364	                && lastName.equalsIgnoreCase(existing.getLastName()))
365	            .count();
366	    }
367	
368	    /**
369	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
370	     * last name and the same address. Last names are compared case-insensitively with collapsed
371	     * whitespace; addresses are compared in their canonical normalized form (see
372	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
373	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
374	     * match on.
375	     */
376	    private List<Owner> findHouseholdMembers(Owner owner) {
377	        String lastName = normalizeHouseholdKey(owner.getLastName());
378	        String address = AddressNormalizer.normalize(owner.getAddress());
379	        if (lastName == null || address == null) {
380	            return List.of();
381	        }
382	        return ownerRepository.findAll().stream()
383	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
384	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
385	            .toList();
386	    }
387	
388	    /**
389	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
390	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
391	     * new one is generated. The resolved value is back-filled onto every member that is missing it
392	     * (or has a different one) so all members of the household share the same identifier.
393	     */
394	    private String resolveHouseholdId(List<Owner> members) {
395	        String householdId = members.stream()
396	            .map(Owner::getHouseholdId)
397	            .filter(id -> id != null && !id.isBlank())
398	            .findFirst()
399	            .orElseGet(() -> UUID.randomUUID().toString());
400	        for (Owner member : members) {
401	            if (!householdId.equals(member.getHouseholdId())) {
402	                member.setHouseholdId(householdId);
403	                ownerRepository.save(member);
404	            }
405	        }
406	        return householdId;
407	    }
408	
409	    /**
410	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
411	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
412	     */
413	    private String normalizeHouseholdKey(String value) {
414	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
415	    }
416	
417	    /**
418	     * Build an owner's {@code customerCode} as {@code '<REGION>-<HASH8>'}: REGION is the region
419	     * code resolved from the owner's postcode (falling back to the owner's city, else
420	     * {@code 'UNKNOWN'}), and HASH8 the first 8 upper-case hex characters of SHA-256 computed over
421	     * the owner's normalized telephone concatenated with the owner's last name (e.g.
422	     * {@code 'NSW-1A2B3C4D'}). There are no per-city sequence numbers; the identity is fully
423	     * derived from the owner's own attributes.
424	     */
425	    private String generateCustomerCode(Owner owner) {
426	        return PostcodeRules.resolveRegion(owner.getPostcode(), owner.getCity()) + "-" + customerHash(owner);
427	    }
428	
429	    /**
430	     * Compute the hash segment of an owner's {@code customerCode}: the first 8 upper-case hex
431	     * characters of SHA-256 over the UTF-8 bytes of the owner's normalized telephone concatenated
432	     * with the owner's last name.
433	     */
434	    private String customerHash(Owner owner) {
435	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
436	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
437	        byte[] digest;
438	        try {
439	            digest = MessageDigest.getInstance("SHA-256")
440	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
441	        } catch (NoSuchAlgorithmException e) {
442	            throw new IllegalStateException("SHA-256 is required but not available", e);
443	        }
444	        StringBuilder hex = new StringBuilder(16);
445	        for (int i = 0; i < 4; i++) {
446	            hex.append(String.format("%02X", digest[i]));
447	        }
448	        return hex.toString();
449	    }
450	
451	    /**
452	     * Count the owners that already exist (before this create) in the same city as {@code owner},
453	     * compared case-insensitively.
454	     */
455	    private long countOwnersInCity(Owner owner) {
456	        String city = owner.getCity();
457	        return ownerRepository.findAll().stream()
458	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
459	            .count();
460	    }
461	
462	    /**
463	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
464	     * on the given {@code date}. Used to enforce the per-day create cap.
465	     */
466	    private long countOwnersRegisteredOn(LocalDate date) {
467	        return ownerRepository.findAll().stream()
468	            .filter(existing -> date.equals(existing.getRegistrationDate()))
469	            .count();
470	    }
471	
472	    /**
473	     * Roll {@code date} forward to the next business day when it falls on a weekend: a Saturday or
474	     * Sunday becomes the following Monday, while a weekday is returned unchanged. Registration dates
475	     * are required to fall on a business day.
476	     */
477	    private LocalDate toBusinessDay(LocalDate date) {
478	        switch (date.getDayOfWeek()) {
479	            case SATURDAY:
480	                return date.plusDays(2);
481	            case SUNDAY:
482	                return date.plusDays(1);
483	            default:
484	                return date;
485	        }
486	    }
487	
488	    /**
489	     * Build an owner's {@code membershipNumber} as {@code '<customerCode>-M<YY>'}, where YY is the
490	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
491	     */
492	    private String generateMembershipNumber(Owner owner) {
493	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
494	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
495	    }
496	
497	    @Override
498	    @Transactional(readOnly = true)
499	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
500	        return ownerRepository.findByLastName(lastName);
501	    }
502	
503	    @Override
504	    @Transactional(readOnly = true)
505	    public Collection<Visit> findVisitsByPetId(int petId) {
506	        return visitRepository.findByPetId(petId);
507	    }
508	
509	    @Override
510	    @Transactional(readOnly = true)
511	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
512	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
513	    }
514	
515	    private <T> T findEntityById(Supplier<T> supplier) {
516	        try {
517	            return supplier.get();
518	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
519	            // Just ignore not found exceptions for Jdbc/Jpa realization
520	            return null;
521	        }
522	    }
523	
524	}
