29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    @Email
58	    private String email;
59	
60	    @Column(name = "registration_date", columnDefinition = "DATE")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date", columnDefinition = "DATE")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "membership_number")
70	    private String membershipNumber;
71	
72	    @Column(name = "household_id")
73	    private String householdId;
74	
75	    @Column(name = "namesake_count")
76	    private Integer namesakeCount;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private boolean bulkSignupWarning;
80	
81	    @Column(name = "household_member_count")
82	    private Integer householdMemberCount;
83	
84	    @Column(name = "possible_duplicate")
85	    private boolean possibleDuplicate;
86	
87	    @Column(name = "possible_duplicate_of")
88	    private Integer possibleDuplicateOf;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    /**
94	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
95	     * another owner already shares the same last name and address. Never persisted or returned.
96	     */
97	    @Transient
98	    private boolean sharesHousehold;
99	
100	    public String getAddress() {
101	        return this.address;
102	    }
103	
104	    public void setAddress(String address) {
105	        this.address = address;
106	    }
107	
108	    public String getCity() {
109	        return this.city;
110	    }
111	
112	    public void setCity(String city) {
113	        this.city = city;
114	    }
115	
116	    public String getPostcode() {
117	        return this.postcode;
118	    }
119	
120	    public void setPostcode(String postcode) {
121	        this.postcode = postcode;
122	    }
123	
124	    public String getTelephone() {
125	        return this.telephone;
126	    }
127	
128	    public void setTelephone(String telephone) {
129	        this.telephone = telephone;
130	    }
131	
132	    public String getEmail() {
133	        return this.email;
134	    }
135	
136	    public void setEmail(String email) {
137	        this.email = email;
138	    }
139	
140	    public LocalDate getRegistrationDate() {
141	        return this.registrationDate;
142	    }
143	
144	    public void setRegistrationDate(LocalDate registrationDate) {
145	        this.registrationDate = registrationDate;
146	    }
147	
148	    public LocalDate getBirthDate() {
149	        return this.birthDate;
150	    }
151	
152	    public void setBirthDate(LocalDate birthDate) {
153	        this.birthDate = birthDate;
154	    }
155	
156	    /**
157	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
158	     * owner's {@code registrationDate} (falling back to the current date when no registration date
159	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
160	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
161	     */
162	    @Transient
163	    public String getAgeBand() {
164	        if (this.birthDate == null) {
165	            return null;
166	        }
167	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
168	        int age = Period.between(this.birthDate, reference).getYears();
169	        if (age < 18) {
170	            return "MINOR";
171	        }
172	        if (age < 65) {
173	            return "ADULT";
174	        }
175	        return "SENIOR";
176	    }
177	
178	    public String getCustomerCode() {
179	        return this.customerCode;
180	    }
181	
182	    public void setCustomerCode(String customerCode) {
183	        this.customerCode = customerCode;
184	    }
185	
186	    public String getMembershipNumber() {
187	        return this.membershipNumber;
188	    }
189	
190	    public void setMembershipNumber(String membershipNumber) {
191	        this.membershipNumber = membershipNumber;
192	    }
193	
194	    public String getHouseholdId() {
195	        return this.householdId;
196	    }
197	
198	    public void setHouseholdId(String householdId) {
199	        this.householdId = householdId;
200	    }
201	
202	    public Integer getNamesakeCount() {
203	        return this.namesakeCount;
204	    }
205	
206	    public void setNamesakeCount(Integer namesakeCount) {
207	        this.namesakeCount = namesakeCount;
208	    }
209	
210	    /**
211	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 3, assigned at creation: it
212	     * starts at 1, gains 1 when an email is present, gains 1 when the owner's name was unique at
213	     * creation time ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
214	     */
215	    @Transient
216	    public Integer getMembershipLevel() {
217	        int level = 1;
218	        if (this.email != null && !this.email.isBlank()) {
219	            level++;
220	        }
221	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
222	            level++;
223	        }
224	        return Math.min(level, 3);
225	    }
226	
227	    /**
228	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
229	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
230	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
231	     * has been assigned yet.
232	     */
233	    @Transient
234	    public Integer getCheckDigit() {
235	        if (this.customerCode == null) {
236	            return null;
237	        }
238	        int sum = 0;
239	        boolean dbl = true;
240	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
241	            char c = this.customerCode.charAt(i);
242	            if (c < '0' || c > '9') {
243	                continue;
244	            }
245	            int d = c - '0';
246	            if (dbl) {
247	                d *= 2;
248	                if (d > 9) {
249	                    d -= 9;
250	                }
251	            }
252	            sum += d;
253	            dbl = !dbl;
254	        }
255	        return (10 - (sum % 10)) % 10;
256	    }
257	
258	    /**
259	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
260	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
261	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
262	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
263	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
264	     */
265	    @Transient
266	    public String getIdentityKey() {
267	        String telephonePart = this.telephone == null ? "" : this.telephone;
268	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
269	        String householdPart = this.householdId == null ? "" : this.householdId;
270	        return telephonePart + "|" + emailPart + "|" + householdPart;
271	    }
272	
273	    public boolean isBulkSignupWarning() {
274	        return this.bulkSignupWarning;
275	    }
276	
277	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
278	        this.bulkSignupWarning = bulkSignupWarning;
279	    }
280	
281	    public Integer getHouseholdMemberCount() {
282	        return this.householdMemberCount;
283	    }
284	
285	    public void setHouseholdMemberCount(Integer householdMemberCount) {
286	        this.householdMemberCount = householdMemberCount;
287	    }
288	
289	    /**
290	     * Whether this owner was flagged at creation as a possible (soft) duplicate: it is not a hard
291	     * {@code identityKey} duplicate, but shares an existing owner's last name and postcode while
292	     * carrying a different telephone. The owner is still created; this flag is advisory.
293	     */
294	    public boolean isPossibleDuplicate() {
295	        return this.possibleDuplicate;
296	    }
297	
298	    public void setPossibleDuplicate(boolean possibleDuplicate) {
299	        this.possibleDuplicate = possibleDuplicate;
300	    }
301	
302	    /**
303	     * The id of the existing owner this one soft-matched against (same last name and postcode,
304	     * different telephone), or {@code null} when {@link #isPossibleDuplicate()} is {@code false}.
305	     */
306	    public Integer getPossibleDuplicateOf() {
307	        return this.possibleDuplicateOf;
308	    }
309	
310	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
311	        this.possibleDuplicateOf = possibleDuplicateOf;
312	    }
313	
314	    public boolean isSharesHousehold() {
315	        return this.sharesHousehold;
316	    }
317	
318	    public void setSharesHousehold(boolean sharesHousehold) {
319	        this.sharesHousehold = sharesHousehold;
320	    }
321	
322	    protected Set<Pet> getPetsInternal() {
323	        if (this.pets == null) {
324	            this.pets = new HashSet<>();
325	        }
326	        return this.pets;
