            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
                && postcode.equals(existing.getPostcode())
                && !Objects.equals(telephone, existing.getTelephone()))
            .min(Comparator.comparing(Owner::getId))
